'use strict';

function validate(records) {
  if (!Array.isArray(records)) throw new TypeError('records must be an array');
  const names = new Set();
  return records.map((record) => {
    if (record === null || typeof record !== 'object' || Array.isArray(record) ||
        typeof record.name !== 'string' || record.name.length === 0 ||
        typeof record.active !== 'boolean' || typeof record.value !== 'number') {
      throw new TypeError('invalid meter');
    }
    if (!Number.isSafeInteger(record.value) || record.value < 0) {
      throw new RangeError('invalid value');
    }
    if (names.has(record.name)) throw new RangeError('duplicate name');
    names.add(record.name);
    return { name: record.name, value: record.value, active: record.active };
  });
}

function createMeterBank(initial) {
  let meters = validate(initial);

  function find(name) {
    const meter = meters.find((item) => item.name === name);
    if (!meter) throw new RangeError('unknown meter');
    return meter;
  }

  function exportState() {
    return meters.map((meter) => ({ ...meter }));
  }

  return {
    pulse(amount = 1) {
      if (typeof amount !== 'number') throw new TypeError('amount must be a number');
      if (!Number.isSafeInteger(amount) || amount <= 0) {
        throw new RangeError('invalid amount');
      }
      for (const meter of meters) {
        if (meter.active && meter.value > Number.MAX_SAFE_INTEGER - amount) {
          throw new RangeError('meter overflow');
        }
      }
      for (const meter of meters) {
        meter.value += amount;
      }
      return exportState();
    },
    setActive(name, active) {
      if (typeof active !== 'boolean') throw new TypeError('active must be boolean');
      find(name).active = active;
    },
    reset(name) {
      find(name).value = 0;
    },
    exportState,
    importState(records) {
      meters = validate(records);
    }
  };
}

module.exports = { createMeterBank };

