'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['createMeterBank']);
const { createMeterBank } = api;

assert.throws(() => createMeterBank(null), TypeError);
assert.throws(() => createMeterBank([null]), TypeError);
assert.throws(() => createMeterBank([{ name: '', value: 0, active: true }]), TypeError);
assert.throws(() => createMeterBank([{ name: 'x', value: '0', active: true }]), TypeError);
assert.throws(() => createMeterBank([{ name: 'x', value: 0, active: 1 }]), TypeError);
assert.throws(() => createMeterBank([{ name: 'x', value: -1, active: true }]), RangeError);
assert.throws(() => createMeterBank([{ name: 'x', value: 1.5, active: true }]), RangeError);
assert.throws(() => createMeterBank([{ name: 'x', value: Number.MAX_SAFE_INTEGER + 1, active: true }]), RangeError);
assert.throws(() => createMeterBank([
  { name: 'x', value: 0, active: true },
  { name: 'x', value: 1, active: false }
]), RangeError);

const source = [
  { name: 'a', value: 2, active: true },
  { name: 'b', value: 9, active: false }
];
const sourceCopy = structuredClone(source);
const bank = createMeterBank(source);
assert.deepEqual(source, sourceCopy);
source[0].value = 500;
assert.deepEqual(bank.exportState(), sourceCopy);

const pulseResult = bank.pulse();
assert.deepEqual(pulseResult, [
  { name: 'a', value: 3, active: true },
  { name: 'b', value: 9, active: false }
]);
pulseResult[0].value = 700;
assert.equal(bank.exportState()[0].value, 3);
bank.setActive('b', true);
assert.deepEqual(bank.pulse(2).map(x => x.value), [5, 11]);
bank.reset('a');
assert.equal(bank.exportState()[0].value, 0);
assert.throws(() => bank.setActive('missing', true), RangeError);
assert.throws(() => bank.reset('missing'), RangeError);
assert.throws(() => bank.setActive('a', 1), TypeError);

for (const invalid of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  const before = bank.exportState();
  assert.throws(() => bank.pulse(invalid), RangeError);
  assert.deepEqual(bank.exportState(), before);
}
assert.throws(() => bank.pulse('1'), TypeError);

const overflow = createMeterBank([
  { name: 'safe', value: 4, active: true },
  { name: 'limit', value: Number.MAX_SAFE_INTEGER, active: true },
  { name: 'inactive', value: Number.MAX_SAFE_INTEGER, active: false }
]);
const beforeOverflow = overflow.exportState();
assert.throws(() => overflow.pulse(1), RangeError);
assert.deepEqual(overflow.exportState(), beforeOverflow);

const imported = [
  { name: 'z', value: 7, active: false },
  { name: 'y', value: 0, active: true }
];
bank.importState(imported);
imported[0].value = 99;
assert.deepEqual(bank.exportState(), [
  { name: 'z', value: 7, active: false },
  { name: 'y', value: 0, active: true }
]);
const beforeBadImport = bank.exportState();
assert.throws(() => bank.importState([
  { name: 'ok', value: 1, active: true },
  { name: 'bad', value: -1, active: false }
]), RangeError);
assert.deepEqual(bank.exportState(), beforeBadImport);
bank.importState([]);
assert.deepEqual(bank.exportState(), []);
const e1 = bank.exportState();
const e2 = bank.exportState();
assert.notStrictEqual(e1, e2);

